pragma solidity ^0.8.36;
library L {
    struct Data { uint256 value; }
    function p() internal pure returns (Data memory) { return Data(7); }
    function p(Data memory self, uint256 value) internal pure returns (Data memory) {
        self.value = value;
        return self;
    }
    function p(uint256 self) internal pure returns (uint256) { return self + 1; }
    function p(uint256 self, uint256 value) internal pure returns (uint256) { return self + value; }
}
contract C {
    using L for *;
    function f(uint256 value) external pure returns (uint256, uint256, uint256) {
        L.Data memory data = L.p();
        data.p(value);
        return (data.value, value.p(), value.p(2));
    }
}
